$p=__DIR__.'/tmp/sessions';if(!is_dir($p))mkdir($p,0770,true);session_save_path($p);session_start();require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(403);exit;}$stages=['Applied','Screening','Interview','Offer','Rejected'];$id=$_POST['id']??'';$stage=$_POST['stage']??'';if(!in_array($stage,$stages,true)){http_response_code(422);exit;}$items=workspaceData('candidates.json',[]);$ok=false;foreach($items as &$x)if(($x['id']??'')===$id){$x['stage']=$stage;$x['updated_at']=date('c');$ok=true;break;}unset($x);if(!$ok){http_response_code(404);exit;}saveWorkspaceData('candidates.json',$items);db()->prepare('UPDATE candidates SET stage=? WHERE id=?')->execute([$stage,$id]);echo json_encode(['ok'=>true]);
